import json
import time

def worker_script(mode):
    return "import os,json,hashlib,subprocess,re\nmode=MODE\nos.makedirs('/work/submission',exist_ok=True)\ncanary=b'NEUTRAL_FIXTURE_NOT_A_MATHEMATICAL_CANDIDATE\\n'\nopen('/work/submission/canary.txt','wb').write(canary)\nprobe={'task_bytes':len(open('/task/TASK.md','rb').read()),'host_absent':not os.path.exists('/ryu/hyunsik/playground/independence/codex/ivy/memory'),'controller_canary_absent':not os.path.exists('host-only-canary.txt'),'auth_absent':not os.path.exists('/home/worker/.codex/auth.json'),'pid_namespace':os.readlink('/proc/self/ns/pid'),'net_namespace':os.readlink('/proc/self/ns/net'),'genericLean_available':os.path.isfile('/opt/lean/bin/lean'),'cache_probe':'neutral'}\nprint(json.dumps(probe),flush=True)\nallowed={'propext','Classical.choice','Quot.sound'}\nstatements={'G':'import Mathlib.Analysis.SpecialFunctions.Sqrt\\n#check Real.sqrt\\n','K':'import RH080EstimatePack\\nexample (hCMS : CMSFunctionalInput.v1.population_reduction) (hN : BRFourierInput.v1.norm_identity) (hU : BRFourierInput.v1.uniform_population_q1) (rh : RiemannHypothesis) : RHAsymptoticGaussian.v4.population_curve ∧ RHWeightedPopulation.v1.sparse_curve ∧ RHWeightedPopulation.v1.flat_curve := ⟨RH080Exposure.Estimates.gaussian hCMS rh,RH080Exposure.Estimates.sparse hN hU rh,RH080Exposure.Estimates.flat hN hU rh⟩\\n#print axioms RH080Exposure.Estimates.gaussian\\n#print axioms RH080Exposure.Estimates.sparse\\n#print axioms RH080Exposure.Estimates.flat\\n','P':'import PopulationActualConsumers\\nexample (hN : BRFourierInput.v1.norm_identity) (hU : BRFourierInput.v1.uniform_population_q1) (rh : RiemannHypothesis) : RHWeightedPopulation.v1.frontier_count := RH080Next.PopulationCanonical.source_first_frontier_count hN hU rh\\n#print axioms RH080Next.PopulationCanonical.source_first_frontier_count\\n'}\nrows=[]\nfor name,source in statements.items():\n path='/work/'+name+'Probe.lean';open(path,'w').write(source);command=['/bin/lean','--root=/work',path];result=subprocess.run(command,capture_output=True,text=True,timeout=180);axes=[set(v.strip()for v in text.split(',')if v.strip())for text in re.findall(r'depends on axioms: \\[([^]]*)\\]',result.stdout)]\n expected=name=='G'or(name=='K'and mode!='A_flat')or(name=='P'and mode=='D_source_PV')\n if expected:passed=result.returncode==0 and len(axes)=={'G':0,'K':3,'P':1}[name]and all(x<=allowed for x in axes)\n else:\n  object_name={'K':'RH080EstimatePack','P':'PopulationActualConsumers'}[name];passed=result.returncode!=0 and not os.path.exists('/source_pv/objects/'+object_name+'.olean')and any(s in result.stdout for s in ['unknown module','does not exist','not found'])\n rows.append({'kind':name,'expected_available':expected,'returncode':result.returncode,'stdout':result.stdout,'stderr':result.stderr,'accepted':passed,'axioms':[sorted(x)for x in axes]});open('/work/submission/'+name+'Probe.lean','w').write(source)\nshared=json.load(open('/source_pv/SHARED_FACTS.json'));shared_checks={}\nfor filename,key in [('FLAT_FACTS.json','statement_json_sha256'),('FLAT_FACTS.txt','statement_text_sha256')]:\n h=hashlib.sha256()\n with open('/source_pv/'+filename,'rb')as f:\n  for block in iter(lambda:f.read(1048576),b''):h.update(block)\n shared_checks[filename]=h.hexdigest()==shared['export'][key]\nsource_present=os.path.isdir('/source_pv/source');graph_present=os.path.isfile('/source_pv/GRAPH.json');representation_ok=(source_present==graph_present==(mode in ['C_network','D_source_PV']))\nvalue={'status':'PASS_ACTUAL_ASSIGNED_PROOF_IMPORT_MANIPULATION'if all(x['accepted']for x in rows)and representation_ok and all(shared_checks.values()) else'FAILED_ACTUAL_ASSIGNED_PROOF_IMPORT_MANIPULATION','mode':mode,'shared_fact_checks':shared_checks,'checks':rows,'actual_lean_path':os.environ.get('LEAN_PATH'),'actual_bin_lean_wrapper':open('/bin/lean').read(),'lean_version':subprocess.check_output(['/bin/lean','--version'],text=True).strip(),'readable_source_present':source_present,'graph_present':graph_present,'representation_expected':representation_ok,'numerical_source_hashes':{name:hashlib.sha256(open('/source_pv/'+name,'rb').read()).hexdigest()for name in ['population_norm.c','flat_population_norm.c']}}\nraw=(json.dumps(value,indent=2)+'\\n').encode();open('/work/submission/PROOF_IMPORTS.json','wb').write(raw);files=[]\nfor name in ['canary.txt','GProbe.lean','KProbe.lean','PProbe.lean','PROOF_IMPORTS.json']:\n data=open('/work/submission/'+name,'rb').read();files.append({'path':name,'sha256':hashlib.sha256(data).hexdigest()})\nopen('/work/submission/LOCK.json','w').write(json.dumps({'files':files}));print(json.dumps({'proof_import_status':value['status'],'mode':mode}),flush=True)\n".replace('MODE',repr(mode),1)

def handler(base,mode):
    class ProofImports(base):
        def do_POST(self):
            import shlex
            data=json.loads(self.rfile.read(int(self.headers['Content-Length'])));self.server.requests.append(data)
            n=len(self.server.requests)
            if n==1:
                script=worker_script(mode)
                arguments={'cmd':'/usr/bin/python3.10 -I -c '+shlex.quote(script),'shell':'/bin/bash','login':False,'yield_time_ms':30000,'max_output_tokens':1500}
                offered={tool.get('name'):tool.get('type')for tool in data.get('tools',[])}
                if offered.get('exec_command')=='function':
                    item={'id':'proof-import-call','type':'function_call','call_id':'proof-import-call','name':'exec_command','arguments':json.dumps(arguments)}
                else:
                    item={'id':'proof-import-call','type':'custom_tool_call','call_id':'proof-import-call','name':'exec','namespace':'functions','input':'text(await tools.exec_command('+json.dumps(arguments)+'));'}
            else:
                item={'id':'final','type':'message','role':'assistant','status':'completed','content':[{'type':'output_text','text':'NEUTRAL_PROOF_IMPORT_FIXTURE_COMPLETE','annotations':[]}]}
            usage={'input_tokens':7,'output_tokens':3,'total_tokens':10,'output_tokens_details':{'reasoning_tokens':1}}
            response={'id':'fixture'+str(n),'object':'response','created_at':int(time.time()),'model':data['model'],'status':'completed','output':[item],'usage':usage}
            events=[{'type':'response.created','response':{**response,'status':'in_progress','output':[]}},{'type':'response.output_item.added','output_index':0,'item':item},{'type':'response.output_item.done','output_index':0,'item':item},{'type':'response.completed','response':response}]
            payload=''.join('event: '+event['type']+'\ndata: '+json.dumps(event)+'\n\n'for event in events).encode()
            self.send_response(200);self.send_header('Content-Type','text/event-stream');self.send_header('Content-Length',str(len(payload)));self.end_headers();self.wfile.write(payload)
    return ProofImports
